    if os.path.isfile(tkrlist_filepath):
        with open(tkrlist_filepath, 'r') as f:
            reader = csv.reader(f)
            lines = list(reader)

        gvkeys = list()
        for line in lines:
            if line[1] == 'Nasdaq':
                gvkeys.append('1'+line[0])
            elif line[1] == 'NYSE':
                gvkeys.append('2'+line[0])
            else:
                gvkeys.append('9'+line[0])  # TODO: is that best way to handle
                                            # unrecognized market?

    else:
        gvkeys = list()

    return gvkeys


